#!/usr/bin/env node
/**
 * ClassPlay — game data generator.
 *
 * Pulls the GameDistribution catalog feed, selects a launch catalog,
 * normalizes it, and writes src/data/games.json which the Astro build
 * consumes. GameMonetize games live in a separate file (src/data/games-gm.json)
 * generated by scripts/fetch-gm.mjs; src/lib/games.mjs merges the two.
 *
 * Usage:  node scripts/fetch-games.mjs
 * No API keys or accounts are required — the feed is public.
 *
 * Selection policy (see research/KEYWORDS.md + research/SOURCES.md):
 *  1. Try to match the KEYWORDS.md top-15 launch titles by name. Those titles
 *     are licensed exclusives of Poki/CrazyGames/official sites, so they are
 *     NOT in syndication feeds — expect near-name matches only (e.g.
 *     "Snow Rider Neo", 2048 variants, subway-runner games). We never label
 *     a page with a game we do not actually embed.
 *  2. Fill the rest with the strongest titles in the same genres
 *     (racing/drifting, endless runners, sports, puzzle/math, .io, 2-player).
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SITE_BASE = 'https://classplay.online';
const OUT = new URL('../src/data/games.json', import.meta.url).pathname;

const GD_FEED = (page) =>
  `https://catalog.api.gamedistribution.com/api/v2.0/rss/All/?collection=all&categories=All&tags=All&subType=all&type=all&mobile=All&rewarded=all&amount=100&page=${page}`;


/** Titles from KEYWORDS.md §3 (top 15) + first alternates — used for matching only. */
const TOP15 = [
  'Slope', 'Snow Rider 3D', 'Retro Bowl', '1v1.LOL', 'Run 3', 'Drift Boss',
  'OvO', 'Monkey Mart', 'Basket Random', 'Drive Mad', 'Eggy Car',
  'Drift Hunters', 'Tunnel Rush', 'Stickman Hook', 'Smash Karts',
  'Cookie Clicker', 'Moto X3M', '2048',
];

function decodeEntities(s = '') {
  return s
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n));
}
function cleanText(s = '', max = 900) {
  const t = decodeEntities(String(s))
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const end = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  return (end > max * 0.4 ? cut.slice(0, end + 1) : cut).trim();
}
/** Light rewrite: keep the feed's factual core, drop its marketing tail, add ours. */
function rewriteDescription(game) {
  let d = cleanText(game.description, 420);
  d = d.replace(/\s*(Play (it |this )?online[^.]*\.?|Play now[^.]*\.?)\s*$/i, '').trim();
  if (d && !/[.!?]$/.test(d)) d += '.';
  const genre = (game.categories[0] || 'browser').toLowerCase();
  return `${d} Play ${game.title} free on ClassPlay — a ${genre} game that runs right in your browser with no downloads or sign-ups, on Chromebooks, laptops and phones.`.trim();
}
function slugify(title) {
  return title.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
function normTitle(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

/** GD thumbnail picker: prefer 512x384 landscape, then 512x512, then first. */
function gdThumb(asset) {
  const list = Array.isArray(asset) ? asset : asset ? [asset] : [];
  return (
    list.find((u) => /512x384/.test(u)) ||
    list.find((u) => /512x512/.test(u)) ||
    list.find((u) => /512x/.test(u)) ||
    list[0] ||
    ''
  );
}

async function fetchJson(url) {
  const res = await fetch(url, { headers: { 'user-agent': 'ClassPlay data builder' } });
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  return res.json();
}

async function main() {
  // ---- pull GD (pages 1..8 = up to 800 games) ------------------------------
  const gdRaw = [];
  for (let p = 1; p <= 8; p++) {
    const page = await fetchJson(GD_FEED(p));
    if (!Array.isArray(page) || page.length === 0) break;
    gdRaw.push(...page);
  }
  console.log(`GD feed: ${gdRaw.length} games`);

  const seen = new Set();
  const games = [];
  const push = (g) => {
    const key = normTitle(g.title);
    if (!key || seen.has(key)) return;
    seen.add(key);
    games.push(g);
  };

  // ---- normalize GD ---------------------------------------------------------
  const gd = gdRaw
    .filter((g) => g && g.Title && g.Url && g.Status !== 'inactive')
    .map((g, i) => {
      const title = decodeEntities(g.Title).trim();
      const categories = (g.Category || []).map((c) => decodeEntities(c));
      return {
        _order: i,
        title,
        slug: slugify(title),
        source: 'gd',
        embedBase: g.Url,
        thumb: gdThumb(g.Asset),
        categories,
        tags: Array.isArray(g.Tag) ? g.Tag.map((t) => decodeEntities(String(t))) : [],
        description: g.Description || '',
        instructions: g.Instructions || '',
        width: +g.Width || 800,
        height: +g.Height || 600,
        mobile: String(g.Mobile).toLowerCase() === 'true' || g.Mobile === true,
      };
    });

  // GM games are generated separately by scripts/fetch-gm.mjs (games-gm.json).
  const gm = [];

  const pool = [...gd.map((g) => ({ ...g })), ...gm.map((g) => ({ ...g }))];

  // ---- step 1: top-15 title matching (exact, then near-name) ------------------
  const matched = [];
  for (const want of TOP15) {
    const nw = normTitle(want);
    let hit = pool.find((g) => normTitle(g.title) === nw);
    let kind = hit ? 'exact' : null;
    if (!hit) {
      // near-name: feed title shares ALL distinctive tokens of the wanted title.
      // Distinctive = length > 2, not a pure number, and not a generic genre word
      // (avoids false hits like "Run 3" -> "Blocky Run").
      const generic = new Set(['run', 'car', 'race', 'racing', 'game', 'games', 'the', 'and']);
      const tokens = nw.split(' ').filter((t) => t.length > 2 && !/^\d+$/.test(t) && !generic.has(t));
      if (tokens.length >= 2 || (tokens.length === 1 && nw.split(' ').length === 1)) {
        hit = pool.find((g) => {
          const nt = normTitle(g.title);
          return tokens.every((t) => nt.split(' ').includes(t)) && nt !== nw;
        });
        kind = hit ? 'near-name' : null;
      }
    }
    if (hit) {
      hit.topMatch = { wanted: want, kind };
      matched.push(`${want} -> ${hit.title} (${kind}, ${hit.source})`);
      push(hit);
    }
  }
  console.log(`Top-15 matches (${matched.length}):`);
  matched.forEach((m) => console.log('  ' + m));

  // ---- step 2: genre fill ------------------------------------------------------
  // Category quotas keep the catalog aligned with the keyword plan:
  // racing/drifting & runners first, then sports, .io, puzzle/math, 2-player.
  const quotas = [
    { label: 'Racing & Driving / Racing', gd: ['Racing & Driving'], gm: ['Racing'], n: 16 },
    { label: 'Agility (runners/skill)', gd: ['Agility'], gm: ['Arcade', 'Hypercasual'], n: 14 },
    { label: 'Sports / Football / Soccer', gd: ['Sports', 'Football'], gm: ['Sports', 'Soccer'], n: 10 },
    { label: '.IO', gd: ['.IO'], gm: ['.IO', 'Multiplayer'], n: 10 },
    { label: 'Puzzle / Merge / Educational (math shelf)', gd: ['Puzzle', 'Merge', 'Educational', 'Match-3'], gm: ['Puzzle'], n: 18 },
    { label: 'Shooter / Battle', gd: ['Shooter', 'Battle'], gm: ['Shooting', 'Action'], n: 10 },
    { label: 'Simulation / Strategy / Casual', gd: ['Simulation', 'Strategy', 'Casual'], gm: ['Clicker', 'Stickman'], n: 10 },
  ];
  const TARGET_TOTAL = 96;
  for (const q of quotas) {
    let added = 0;
    // GD first (primary source), in feed order (feed is popularity-ordered)
    for (const g of gd) {
      if (added >= q.n || games.length >= TARGET_TOTAL) break;
      if (q.gd.some((c) => g.categories.includes(c)) && cleanText(g.description).length >= 60) {
        if (!seen.has(normTitle(g.title))) { push(g); added++; }
      }
    }
    for (const g of gm) {
      if (added >= q.n || games.length >= TARGET_TOTAL) break;
      if (q.gm.some((c) => g.categories.includes(c)) && cleanText(g.description).length >= 60) {
        if (!seen.has(normTitle(g.title))) { push(g); added++; }
      }
    }
    console.log(`quota ${q.label}: +${added}`);
  }
  // safety net: top up from GD in feed order if still short of 60
  for (const g of gd) {
    if (games.length >= 60) break;
    if (cleanText(g.description).length >= 60) push(g);
  }

  // ---- finalize ------------------------------------------------------------------
  const finalGames = games.map((g, idx) => {
    const pageUrl = `${SITE_BASE}/games/${g.slug}/`;
    const embedUrl =
      g.source === 'gd'
        ? `${g.embedBase}${g.embedBase.includes('?') ? '&' : '?'}gd_sdk_referrer_url=${encodeURIComponent(pageUrl)}`
        : g.embedBase;
    return {
      title: g.title,
      slug: g.slug,
      source: g.source,
      embedUrl,
      pageUrl,
      thumb: g.thumb,
      categories: g.categories,
      tags: g.tags.slice(0, 8),
      description: rewriteDescription({ ...g, title: g.title, categories: g.categories }),
      instructions: cleanText(g.instructions, 700),
      width: g.width,
      height: g.height,
      mobile: g.mobile,
      featured: idx < 12,
      topMatch: g.topMatch || null,
    };
  });

  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, JSON.stringify(finalGames, null, 2));
  console.log(`Wrote ${finalGames.length} games -> ${OUT}`);
  console.log(`  GD: ${finalGames.filter((g) => g.source === 'gd').length}  GM: ${finalGames.filter((g) => g.source === 'gm').length}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
